    "explanation": "表から順に数えていけば解ける問題である。\n【ア】変更前は各選挙区で上位2人が当選する。a区はC(65)とB(25)、b区はC(45)とB(30)、c区はC(65)とB(20)、d区はA(60)とB(25)、e区はA(40)とB(35)が当選する。当選者数はA党2人、B党5人、C党3人。一方、得票数の合計はA党150、B党135、C党215で、最も少ないのはB党である。そのB党の当選者数が5人で最多なのだから、アには「多い」が入る。\n【ウ】変更後は各選挙区の1位だけが当選する。a・b・c区はC党、d・e区はA党が勝ち、当選者数はA党2人、B党0人、C党3人。得票数の合計が最も少ないB党の当選者数は0人で最少なので、ウには「少ない」が入る。\n【イ】死票とは落選した候補者に投じられた票である。変更前は各区で3位の票だけが死票になるので10＋25＋15＋15＋25＝90票。変更後は各区で2位・3位の票がすべて死票になるので35＋55＋35＋40＋60＝225票。よって死票は「増加」する。\n以上より、ア＝多い、イ＝増加、ウ＝少ない。B党のように「広く薄く」票を集める政党は、中選挙区制では議席を取りやすく、小選挙区制では議席を失いやすい。小選挙区制は死票が多く出る一方で、大政党に有利に働き政権が安定しやすいという特徴をもつ。",
