    "question": "近代国家の成立について調べた生徒Xは、国家の強制力に関する次の資料をみつけた（なお、資料には表記を改めた箇所や省略した箇所がある）。資料から読みとれる内容として最も適当なものを、後のうちから一つ選べ。\n\n【資料】\n　「もちろん暴力行使は、国家にとってノーマルな手段でもまた唯一の手段でもない…（略）…が、おそらく国家に特有な手段ではあるだろう。そして実際今日、この暴力に対する国家の関係は特別に緊密なのである。過去においては、氏族（ジッペ）を始めとする多種多様な団体が、物理的暴力をまったくノーマルな手段として認めていた。ところが今日では、次のように言わねばなるまい。国家とは、ある一定の領域の内部で…（略）…正当な物理的暴力行使の独占を（実効的に）要求する人間共同体である、と。国家以外のすべての団体や個人に対しては、国家の側で許容した範囲内でしか、物理的暴力行使の権利が認められないということ、つまり国家が暴力行使への『権利』の唯一の源泉とみなされているということ、これは確かに現代に特有な現象である。」\n（注）「氏族」とは、共通の祖先をもつ人々の集団のことをいう。\n（出所）マックス・ヴェーバー（ウェーバー）『職業としての政治』脇圭平訳",
