    "question": "政治体制について二つの次元で類型化を試みる理論を参考に、いくつかの国のある時期の政治体制の特徴を比較し、図中に位置づけてみた。図中のa～cのそれぞれには、次の政治体制ア～ウのいずれかが当てはまる。その組合せとして最も適当なものを、後のうちから一つ選べ。\n\n（図の二つの軸）\n　i．包括性（参加）：選挙権がどれだけの人々に認められているか（右にいくほど、多くの人々に認められている）。\n　ii．自由化（公的異議申立て）：選挙権を認められている人々が、抑圧なく自由に政府に反対したり対抗したりできるか（上にいくほど、抑圧なく自由にできる）。\n\nア　日本国憲法下の日本の政治体制\nイ　チャーティスト運動の時期のイギリスの政治体制\nウ　ゴルバチョフ政権より前のソ連の政治体制",
