    "answer": 6,
    "explanation": "【ア】閣議の決定は全会一致によることが慣行となっている。憲法や法律に明文の規定はないが、内閣は国会に対して連帯して責任を負う（憲法66条3項）ため、内閣の意思は一つにまとまっている必要があるとされるからである。閣議決定に反対する大臣がいる場合、首相はその大臣を罷免して決定することができる。\n【イ】日本国憲法下の内閣総理大臣は「内閣の首長」（憲法66条1項）と位置づけられ、国務大臣の任免権（68条）をもつ強い立場にある。「同輩中の首席」は、他の国務大臣と対等な立場にすぎなかった大日本帝国憲法下の内閣総理大臣を表す言葉なので誤り。\n【ウ】憲法74条は「法律及び政令には、すべて主任の国務大臣が署名し、内閣総理大臣が連署することを必要とする」と定めている。よってウ＝内閣総理大臣。\n明治憲法下と日本国憲法下で首相の地位が大きく変わったこと（同輩中の首席→内閣の首長）は頻出のポイントである。",
