    "explanation": "【ア】憲法第99条は「天皇又は摂政及び国務大臣、国会議員、裁判官その他の公務員は、この憲法を尊重し擁護する義務を負ふ」と定めており、義務を負うのは公権力を担う側であって国民ではない。憲法が国家権力を縛るものだという立憲主義の考え方が、この条文に表れている。よってaが当てはまる。\n【イ】憲法第84条は「あらたに租税を課し、又は現行の租税を変更するには、法律又は法律の定める条件によることを必要とする」と定める（租税法律主義）。納税の義務を定める第30条も「法律の定めるところにより」としており、憲法の規定だけで具体的な納税義務が生じるわけではなく、税目・税率などを定める法律が必要である。よってcが当てはまる。\n以上より、ア＝a、イ＝cの組合せとなる。",
