    "explanation": "3が正解。人間の安全保障とは、安全保障を「国家を守ること」ではなく「一人ひとりの人間を守ること」としてとらえ直す考え方である。紛争、貧困、飢餓、感染症、環境破壊、災害など、人々の生存・生活・尊厳を脅かすあらゆる脅威から個人を守り（保護）、自ら立ち向かえる力をつける（能力強化＝エンパワーメント）ことをめざす。\n1994年の国連開発計画（UNDP）『人間開発報告書』で打ち出され、日本は開発協力大綱でもこれを指導理念に掲げている。資料の「個人の保護と能力強化」「恐怖と欠乏からの自由」「一人ひとりが幸福と尊厳を持って生存する権利」という表現がそのまま手がかりになる。",
