    "explanation": "市場の失敗とは、市場に任せておいても資源が効率的に配分されない状態をいう。代表例は独占・寡占、外部性（外部経済・外部不経済）、公共財、情報の非対称性である。ア：正しい。特定企業が価格支配力をもつ独占・寡占は市場の失敗の典型例である。イ：正しい。市場を通さずに周辺住民が不利益を被るのは外部不経済（公害など）にあたる。ウ：誤り。売り手の情報をすべて買い手ももっている状態は情報が対称であるということで、これは完全競争市場が成り立つ前提条件であって失敗ではない。市場の失敗となるのは、その逆の情報の非対称性である。よってアとイ。",
