    "question": "付加価値について身近な例で考えるために作成した次のメモ中の空欄　ア　～　オ　には、それぞれ数値が入る。空欄　エ　・　オ　に入る数値の組合せとして正しいものを、後のうちから一つ選べ。\n\n【メモ】\n　国で生産できる財が「小麦」、「小麦粉」、「パン」だけであると仮定し、小麦を生産する農家、その小麦を小麦粉にする製粉会社、その小麦粉でパンを作る製パン会社からなる経済を考える。ここでは、1年間に小麦500袋と小麦粉1,000kgとパン10,000個とが生産されたとする。農家は、生産した小麦のすべてを製粉会社に計50万円で販売した。製粉会社は、その小麦をすべて加工して1,000kgの小麦粉を生産し、それをすべて製パン会社に計150万円で販売した。製パン会社は、製粉会社から購入した小麦粉をすべて使って10,000個のパンを製造し、それをすべて消費者に計400万円で販売した。製パン会社、製粉会社、農家のそれぞれの生産に必要な中間投入物は、小麦、小麦粉以外にはないものとする。\n　ここまでを整理すると図の表のようになる。\n　以上のような経済活動が行われた場合、製パン会社の生み出した付加価値額は　エ　万円であり、この国のGDPは　オ　万円である。",
