    "explanation": "三つのグラフを、縦軸の目盛りの大きさと形の両面から見分ける問題である。\nまず金額の規模で絞り込める。資料2は－1兆円～3兆円、資料3は－10兆円～15兆円、資料4は0～25兆円と、目盛りの幅が大きく違う。一国の経済全体を表すGDPの増減額が最も大きくなるはずなので、資料4（ウ）がGDPである。逆に、増減額が最も小さい資料2（ア）は、GDPや設備投資に比べて金額の小さい民間部門の在庫と判断できる。残る資料3（イ）が民間設備投資となる。\n次に資料1の説明と照らして裏づけをとる。バブル崩壊後の1992年前後に、資料3（設備投資）は大きくマイナスに転じており、「景気の後退は…設備投資の減少を促す」という記述と合う。資料2（在庫）も1992年以降マイナスになっており、「過剰在庫の処分」の動きと整合する。\nよってア＝民間部門の在庫、イ＝民間設備投資、ウ＝GDP。",
