    "question": "日本では、1990年代初頭にバブル経済が崩壊した後、銀行の不良債権処理や貸し渋りの問題に対処するため、公的資金が投入された。\n　銀行のバランスシート（貸借対照表）の動きを表した図の模式図について、簡略化のため、銀行の負債はすべて預金、純資産は資本金のみとする。この図では、銀行の貸出債権が経済不況時に不良債権化し、その不良債権が処理されるまでの流れが示されている。不良債権となっている資産を最終的に消滅させるために費用が発生し、その費用が大きければ損失が発生し資本金を減少させることがある。その減少が多額であれば、資本金を増やすために公的資金が投入されることもある。\n　以上の説明と模式図を踏まえて、不良債権問題に関連する記述として最も適当なものを、後のうちから一つ選べ。",
