    "answer": 1,
    "explanation": "2が誤り。ブレトンウッズ体制（IMF協定、1944年）で金との交換を約束したのは、基軸通貨であるアメリカのドルだけである（金1オンス＝35ドル）。他の加盟国はドルに対して自国通貨の平価を定め、その相場を維持する義務を負った。つまり「金－ドル－各国通貨」という二段構えの仕組みであり、すべての加盟国に金交換義務があったわけではない。\nこの点をおさえると、他の選択肢の流れも理解しやすい。1930年代は各国が金本位制を捨てて自国通貨を切り下げ、輸出を伸ばして不況を脱しようとした（近隣窮乏化政策）。その反省からブレトンウッズ体制の固定相場制が作られたが、アメリカの国際収支悪化とベトナム戦争でドルが海外に流出し、金と交換できるのかという不安（ドル危機）が広がった。1971年のニクソン・ショックで金とドルの交換が停止され、1973年から主要国は変動相場制へ移行した。その後はサミットやG7・G20といった協議の場で通貨・経済問題を話し合っている。",
