    "question": "貧困のない世界をめざした多様な活動の例として、マイクロファイナンス（マイクロクレジット）について発表することにした。次の資料は発表用のスライドの一部である。資料中の空欄　ア　・　イ　に当てはまる語句の組合せとして最も適当なものを、後のうちから一つ選べ。\n\n【資料（スライド）】\n　◇マイクロファイナンス（マイクロクレジット）とは？\n　　→貧困層や低所得層向けの少額融資などの金融サービス。融資は　ア　で行われるとされる。\n　◇この活動の具体例\n　　→　イ　……バングラデシュで設立。高い返済率を記録。2006年にノーベル平和賞を受賞。",
