    "question": "日本、韓国、中国の2000年、2010年および2020年の実質GDP成長率、一人当たり実質GDP、一般政府総債務残高の対GDP比を調べ、次の表にまとめた。表中のA～C国はこれら3か国のいずれかである。後の記述ア～ウは、これら3か国についてそれぞれ説明したものである。A～C国と記述ア～ウの組合せとして最も適当なものを、次のうちから一つ選べ。\n\n【表】（左から2000年／2010年／2020年）\nA国　実質GDP成長率（対前年比：％）　2.8／4.1／−4.8\n　　　一人当たり実質GDP（米ドル）　36,230.9／38,111.4／40,048.3\n　　　一般政府総債務残高（対GDP比：％）　135.6／205.7／256.2\nB国　実質GDP成長率（対前年比：％）　9.1／6.8／−1.0\n　　　一人当たり実質GDP（米ドル）　22,988.1／34,431.1／42,297.8\n　　　一般政府総債務残高（対GDP比：％）　16.7／29.5／48.7\nC国　実質GDP成長率（対前年比：％）　8.5／10.8／2.3\n　　　一人当たり実質GDP（米ドル）　3,427.6／8,836.9／16,296.6\n　　　一般政府総債務残高（対GDP比：％）　23.0／33.9／66.8\n（注）一人当たり実質GDPは購買力平価換算したものを用いており、基準年は2017年である。また、一般政府には中央政府と地方政府とが含まれる。（出所）IMFウェブページにより作成。\n\nア　この国は、1978年からの改革開放政策の下で、外資導入などにより経済成長を続けてきた。この国の経済運営方針は、低・中所得国にとって、一つの経済発展モデルになっている。\nイ　この国は、1960年代から工業化による経済成長が進み、NIESの一つに数えられた。その後、アジア通貨危機による経済危機も克服し、現在はアジア有数の高所得国となっている。\nウ　この国は、1950年代から1973年頃まで高度経済成長を遂げ、急速に欧米の先進国に追いついた。しかし、1990年代以降は低成長が常態化しており、政府部門の累積赤字の拡大が議論の的となっている。",
