    "explanation": "前半：支出面からみた国内総生産（GDP）では、民間最終消費支出が最大の項目で全体のおよそ5割強～6割を占め、民間企業設備投資はおよそ1～2割にとどまる。したがって支出割合は民間企業設備投資の方が小さい。\n後半：対前年度増加率＝（今年度の量−前年度の量）÷前年度の量×100 である。分母（前年度の額）は民間最終消費支出の方が大きく、分子（増加額）はメモより民間企業設備投資（3兆1,698億円）の方が民間最終消費支出（2兆3,211億円）より大きい。分母が小さく分子が大きい民間企業設備投資の方が、増加率は高くなる。\nよって前半・後半ともに正しいのは選択肢1である。増加「額」と増加「率」を区別することが要点である。",
